// Run in an isolated agent-browser session: agent-browser eval --stdin < this-file
(async()=>{
const wait=()=>new Promise(r=>setTimeout(r,180)),check=(v,t)=>{if(!v)throw Error(t)};
const click=async(text,scope=document)=>{const el=[...scope.querySelectorAll('button,a')].find(e=>e.textContent.trim()===text);check(el,'missing button '+text);el.click();await wait()};
const fill=async(label,value)=>{const field=[...document.querySelectorAll('.field')].find(e=>e.querySelector('label')?.textContent.replace(' *','').trim()===label);const el=field?.querySelector('input:not([type=hidden]),textarea');check(el,'missing input '+label);const proto=el.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(proto,'value').set.call(el,value);el.dispatchEvent(new Event('input',{bubbles:true}));await wait()};
const choose=async(label,value)=>{document.querySelector(`[role=combobox][aria-label="${label}"]`).click();await wait();await click(value,document.querySelector('[role=listbox]'))};
location.hash='/overview';await wait();check(document.querySelector('[aria-label="区域导航"]').textContent.includes('全部项目'),'tenant project menu missing');await choose('项目','Northstar · 新品发布');check(document.querySelector('main h1').textContent.includes('新品发布'),'instance workbench is not overview');check(!document.querySelector('[aria-label="区域导航"]').textContent.includes('全部项目'),'instance still has all projects');
[...document.querySelectorAll('.primary-nav a')].find(e=>e.textContent.trim()==='协作').click();await wait();const nav=document.querySelector('[aria-label="区域导航"]');check(!nav.textContent.includes('全部项目')&&!nav.textContent.includes('项目概览'),'collaboration contains overview/project menus');check(nav.textContent.includes('工作流'),'workflow naming missing');
const shell=document.querySelector('.app-shell'),top=document.querySelector('.primary-nav');await click('工作流',nav);check(document.querySelector('.app-shell')===shell&&document.querySelector('.primary-nav')===top,'workflow menu remounted application shell');check(location.hash.split('?')[0]==='#/p/launch/flow','workflow menu lost exact project URL');check(document.querySelector('main h1')?.textContent==='工作流'&&!document.querySelector('.react-flow'),'workflow entry is not definition list');check([...document.querySelectorAll('.sidebar .panel-button')].some(e=>e.textContent.trim()==='工作流'&&e.classList.contains('active')),'workflow menu lost selection');await click('查看 / 编辑定义');check(new URLSearchParams(location.hash.split('?')[1]).get('workflow_id')==='default','workflow definition identity absent URL');check(!!document.querySelector('.node-panel'),'node inspector missing');await click('编辑新草案');await click('添加节点');const ai=[...document.querySelectorAll('.node-library>button')].find(e=>e.querySelector('b').textContent==='AI 任务');ai.click();await wait();check(document.querySelector('.node-panel').textContent.includes('节点指令 / 提示词'),'AI parameters missing');await fill('节点名称','新的分析节点');await click('复制',document.querySelector('.node-panel'));check(document.querySelector('.node-panel h2').textContent.includes('副本'),'duplicate failed');await click('删除',document.querySelector('.node-panel'));await click('确认继续');await click('确认发布新版本');check(document.querySelector('.workflow-issues').textContent.includes('缺少上游输入'),'disconnected node not rejected');await click('模拟预览',document.querySelector('.node-panel'));check(document.querySelector('.node-panel').textContent.includes('不产生真实运行记录')&&!document.querySelector('.node-panel').textContent.includes('模拟通过'),'node preview fabricates successful execution');
location.hash='/p/launch/work-items?view=calendar';await wait();check(document.querySelector('.calendar-grid'),'calendar missing');await click('周');await choose('排期成员','我的排期 · 林予');const event=[...document.querySelectorAll('.calendar-task')].find(e=>e.textContent.includes('新品落地页'));check(event,'personal scheduled task missing');event.click();await wait();await fill('开始日期','2026-10-15');await fill('结束日期','2026-10-19');await fill('调整说明','浏览器排期验收');await click('保存排期');let s=JSON.parse(localStorage.getItem('collaboration-prototype-v1'));check(s.work.find(w=>w.id==='W-104').plannedEnd==='2026-10-19','schedule not shared');
location.hash='/chat?execution_id=EX-demo-W-104';await wait();if(matchMedia('(max-width: 1250px)').matches){document.querySelector('[aria-label="切换会话上下文"]').click();await wait();}check(document.querySelector('[role=tablist][aria-label="任务预览标签"]'),'preview tabs missing');check(!document.querySelector('[aria-label="添加预览标签"]'),'manual tab addition remains');await click('API');await fill('请求路径','/healthz');await click('模拟请求');check(document.querySelector('.preview-api pre').textContent.includes('/healthz'),'API response missing');await click('仓库代码');await click('API');check(document.querySelector('.preview-api input').value==='/healthz','tab switch lost local state');await click('模拟断线',document.querySelector('[role=tabpanel]:not([hidden])'));check(document.querySelector('[role=tabpanel]:not([hidden])').textContent.includes('预览连接已断开'),'disconnect state missing');await click('重新连接',document.querySelector('[role=tabpanel]:not([hidden])'));check(document.querySelector('.preview-api input').value==='/healthz','reconnect lost inputs');check(!document.querySelector('[aria-label="关闭 API"]'),'manual tab deletion remains');
return {pass:true,checks:['tenant/instance navigation boundaries','workflow exact URL with stable application shell','node library edit duplicate delete honest preview','publish validation','personal calendar schedule sync','preview add switch state disconnect close']};
})()
